class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}  # student -> {assignment -> grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be between 2.0 and 5.0")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            return 0.0

        student_grades = self.grades[student]

        # Get all assignments that this student has grades for
        relevant_assignments = []
        for assignment_name in student_grades:
            if assignment_name in self.assignments:
                weight, kind = self.assignments[assignment_name]
                relevant_assignments.append((assignment_name, weight, kind, student_grades[assignment_name]))

        if not relevant_assignments:
            return 0.0

        # Separate homework and quiz grades
        homework_grades = []
        quiz_grades = []

        for assignment_name, weight, kind, grade in relevant_assignments:
            if kind == "homework":
                homework_grades.append((weight, grade))
            elif kind == "quiz":
                quiz_grades.append((weight, grade))

        # If there's more than one quiz, drop the lowest one
        if len(quiz_grades) > 1:
            # Sort by grade (ascending) and remove the lowest
            quiz_grades.sort(key=lambda x: x[1])
            quiz_grades = quiz_grades[1:]

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        for weight, grade in homework_grades:
            weighted_sum += weight * grade
            total_weight += weight

        for weight, grade in quiz_grades:
            weighted_sum += weight * grade
            total_weight += weight

        # Handle case where total_weight is 0
        if total_weight == 0.0:
            return 0.0

        average_grade = weighted_sum / total_weight
        return round(average_grade, 2)
